CREATE OR ALTER FUNCTION [dbo].[GetAssetsOfDefaultPermissionsAssetID] ( @ResourceID int, @AssetTypeID int, @DefaultPermissions bit, @IsAdministrator bit, @AssetDetail bit = 0, @AssetID bigint = 0 ) RETURNS @tbl TABLE ( PermissionsBitMask int, AssetID bigint, AssetTypeID int, Index idx_tbl clustered(AssetID,AssetTypeID) ) as Begin declare @IsResposibilyFortypeID bit = 0;
declare @RespAssets table (AssetID Bigint, index ix_RespAssets (AssetID));
if (@DefaultPermissions = 0 and @IsAdministrator = 0) begin -- check entire assettypeid rule exists select top 1 @IsResposibilyFortypeID = 1 from ResponsibilitySummary where AssetTypeId = @AssetTypeID and ResourceID = @ResourceID and AssetID = 0 and ApplyToType = 1;
if (@IsResposibilyFortypeID = 0) begin if not exists (select 1 from ResponsibilitySummary R where R.assetid = @AssetID and r.ResourceID = @ResourceID and @AssetID > 0) begin if exists (select 1 from Asset A inner join ResponsibilitySummary R on R.assetid = A.ID and r.ResourceID = @ResourceID where A.AssetTypeID = @AssetTypeID) Begin if (@AssetID > 0) Begin insert into @tbl select 0 as PermissionsBitMask, @AssetID as AssetID, @AssetTypeID AssetTypeID End end else begin if (@AssetDetail = 0) begin insert into @tbl select 0 as PermissionsBitMask, 0 as AssetID, @AssetTypeID AssetTypeID end else begin insert into @tbl select 0 as PermissionsBitMask, @AssetID as AssetID, @AssetTypeID AssetTypeID; end end end end end return End
